export const queue = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Front desk queue</title>\n<style>\n:root{--bg:#fafaf7;--card:#fff;--ink:#1d2433;--mut:#667;--line:#e3e5ea;--warn:#b3261e;--ok:#1b6e4a}\n@media(prefers-color-scheme:dark){:root{--bg:#14161b;--card:#1c1f26;--ink:#e8eaf0;--mut:#9aa3b2;--line:#2c313b;--warn:#f2827a;--ok:#6fcf9f}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif}\nmain{max-width:860px;margin:0 auto;padding:20px 16px 60px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin-bottom:20px}\nh2{font-size:15px;margin:26px 0 8px;display:flex;gap:8px;align-items:center}.n{background:var(--warn);color:#fff;border-radius:10px;padding:0 8px;font-size:12px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:8px 0;display:flex;gap:12px;justify-content:space-between;align-items:flex-start}\n.t{font-weight:600}.m{color:var(--mut);font-size:13px}button{font:inherit;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:6px 12px;cursor:pointer}\n.empty{color:var(--mut);padding:8px 0}a{color:inherit}\n</style></head><body><main>\n<h1>Front desk queue</h1><div class=\"sub\">Things to do now. Open <a href=\"/calendar\">designer calendars</a> · <a href=\"/calls\">all calls</a>.</div>\n<div id=\"out\">Loading…</div></main>\n<script>\nconst key=localStorage.getItem('key')||prompt('Access key');localStorage.setItem('key',key||'');\nconst api=(p,o={})=>fetch(p,{...o,headers:{'x-api-key':key,'content-type':'application/json'}}).then(r=>r.json());\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst when=d=>new Date(d).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'});\nfunction sec(title,rows,render,btn){return `<h2>${title}<span class=\"n\" ${rows.length?'':'style=\"background:var(--ok)\"'}>${rows.length}</span></h2>`+(rows.length?rows.map(r=>`<div class=\"card\"><div>${render(r)}</div>${btn?`<button data-id=\"${r.id}\" data-a=\"${btn[1]}\">${btn[0]}</button>`:''}</div>`).join(''):'<div class=\"empty\">Nothing waiting.</div>')}\nasync function load(){\n const q=await api('/api/queue');if(q.error){document.getElementById('out').textContent='Access key not accepted. Clear it and reload.';localStorage.removeItem('key');return}\n document.getElementById('out').innerHTML=\n sec('Escalations: call back within 15 minutes',q.escalations,r=>`<div class=\"t\">${esc(r.caller_name||'Caller')} · ${esc(r.caller_phone||'no number')}</div><div class=\"m\">${when(r.created_at)} · ${esc(r.summary||'')}</div>`,['Done','done'])+\n sec('Callbacks owed (missed or dropped calls)',q.callbacks,r=>`<div class=\"t\">${esc(r.caller_phone||'no number')}</div><div class=\"m\">${when(r.created_at)}</div>`,['Done','done'])+\n sec('Declined calls to review',q.declines,r=>`<div class=\"t\">${esc(r.caller_name||'Caller')} · ${esc(r.area||'')}</div><div class=\"m\">${when(r.created_at)} · Reason: ${esc(r.decline_reason||'')}</div><div class=\"m\">${esc(r.summary||'')}</div>`,['Reviewed','reviewed'])+\n sec('Bookings at risk (call-by time passed or no slot in window)',q.lateBookings,r=>`<div class=\"t\">${esc(r.caller_name||'Lead')} · ${esc(r.designer)} · ${esc(r.tier)}</div><div class=\"m\">Call by ${when(r.call_by)}</div>`,['Done','done']);\n}\ndocument.addEventListener('click',async e=>{const b=e.target.closest('button[data-id]');if(!b)return;b.disabled=true;await api('/api/review',{method:'POST',body:JSON.stringify({id:Number(b.dataset.id),action:b.dataset.a})});load()});\nload();setInterval(load,15000);\n</script></body></html>\n";
export const calendar = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Designer calendars</title>\n<style>\n:root{--bg:#fafaf7;--card:#fff;--ink:#1d2433;--mut:#667;--line:#e3e5ea;--hot:#b3261e;--pri:#a15c00;--std:#1b6e4a}\n@media(prefers-color-scheme:dark){:root{--bg:#14161b;--card:#1c1f26;--ink:#e8eaf0;--mut:#9aa3b2;--line:#2c313b;--hot:#f2827a;--pri:#f0b45c;--std:#6fcf9f}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 -apple-system,Segoe UI,Helvetica,Arial,sans-serif}\nmain{max-width:1000px;margin:0 auto;padding:20px 16px 60px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin-bottom:16px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}\n.d{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px}.d.next{outline:2px solid var(--std)}\n.d h3{margin:0 0 6px;font-size:15px;display:flex;justify-content:space-between}.tag{font-size:11px;color:var(--std);font-weight:600}\n.b{border-left:3px solid var(--std);padding:2px 8px;margin:5px 0}.b.hot{border-color:var(--hot)}.b.priority{border-color:var(--pri)}.m{color:var(--mut);font-size:12px}.empty{color:var(--mut);font-size:13px}a{color:inherit}\n</style></head><body><main>\n<h1>Designer calendars</h1><div class=\"sub\">One calendar per designer. The next lead goes to the highlighted designer. <a href=\"/queue\">Front desk queue</a> · <a href=\"/calls\">All calls</a></div>\n<div class=\"grid\" id=\"g\">Loading…</div></main>\n<script>\nconst key=localStorage.getItem('key')||prompt('Access key');localStorage.setItem('key',key||'');\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst when=d=>new Date(d).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'});\nasync function load(){\n const r=await fetch('/api/calendar',{headers:{'x-api-key':key}}).then(r=>r.json());\n if(r.error){document.getElementById('g').textContent='Access key not accepted. Clear it and reload.';localStorage.removeItem('key');return}\n document.getElementById('g').innerHTML=r.designers.map((d,i)=>{\n  const bs=r.bookings.filter(b=>b.designer_id===d.id);\n  return `<div class=\"d ${i===r.next_designer_index?'next':''}\"><h3>${esc(d.name)}<span class=\"tag\">${i===r.next_designer_index?'NEXT LEAD':''}</span></h3>`+\n  (bs.length?bs.map(b=>`<div class=\"b ${esc(b.tier)}\"><div>${when(b.start_at)}</div><div class=\"m\">${esc(b.caller_name||'Lead')} · ${esc(b.area||'')} · ${esc(b.tier)}${b.status!=='new'?' · '+esc(b.status):''}</div></div>`).join(''):'<div class=\"empty\">Free this week</div>')+'</div>'}).join('');\n}\nload();setInterval(load,10000);\n</script></body></html>\n";
export const calls = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>All calls</title>\n<style>\n:root{--bg:#fafaf7;--card:#fff;--ink:#1d2433;--mut:#667;--line:#e3e5ea;--ok:#1b6e4a;--warn:#b3261e;--amb:#a15c00}\n@media(prefers-color-scheme:dark){:root{--bg:#14161b;--card:#1c1f26;--ink:#e8eaf0;--mut:#9aa3b2;--line:#2c313b;--ok:#6fcf9f;--warn:#f2827a;--amb:#f0b45c}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 -apple-system,Segoe UI,Helvetica,Arial,sans-serif}\nmain{max-width:1000px;margin:0 auto;padding:20px 16px 60px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin-bottom:14px}a{color:inherit}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:14px}.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px}.tile b{display:block;font-size:22px}\n.filters{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}button{font:inherit;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:8px;padding:5px 12px;cursor:pointer}button.on{background:var(--ink);color:var(--bg)}\n.row{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 14px;margin:8px 0}.top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.t{font-weight:600}.m{color:var(--mut);font-size:13px}\n.pill{font-size:12px;font-weight:600;border-radius:10px;padding:1px 9px;border:1px solid currentColor}.qualified{color:var(--ok)}.declined{color:var(--warn)}.escalated{color:var(--amb)}.missed,.info_only{color:var(--mut)}\n.hot{color:var(--warn)}.priority{color:var(--amb)}.standard{color:var(--ok)}\n</style></head><body><main>\n<h1>All calls</h1><div class=\"sub\">Every call with its qualification status. Transcripts and recordings are in <a href=\"https://app.vaanivoice.ai/conversations/history\" target=\"_blank\" rel=\"noopener\">Vaani, Conversations, History</a>. · <a href=\"/queue\">Front desk queue</a> · <a href=\"/calendar\">Designer calendars</a></div>\n<div class=\"tiles\" id=\"tiles\"></div><div class=\"filters\" id=\"filters\"></div><div id=\"list\">Loading…</div></main>\n<script>\nconst key=localStorage.getItem('key')||prompt('Access key');localStorage.setItem('key',key||'');\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst when=d=>d?new Date(d).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):'';\nlet all=[],filter='all';\nfunction draw(){\n const rows=all.filter(c=>filter==='all'||c.outcome===filter);\n document.getElementById('list').innerHTML=rows.length?rows.map(c=>`<div class=\"row\"><div class=\"top\"><div><span class=\"t\">${esc(c.caller_name||'Caller')}</span> <span class=\"m\">${esc(c.area||'')} ${esc(c.project_type||'')}</span></div><div><span class=\"pill ${esc(c.outcome)}\">${esc(c.outcome.replace('_',' '))}</span> ${c.tier?`<span class=\"pill ${esc(c.tier)}\">${esc(c.tier)}</span>`:''}</div></div>\n <div class=\"m\">${when(c.created_at)}${c.caller_phone?' · '+esc(c.caller_phone):''}${c.designer?' · Designer '+esc(c.designer)+' at '+when(c.slot_start):''}${c.status&&c.status!=='new'?' · status: '+esc(c.status):''}</div>\n ${c.decline_reason?`<div class=\"m\">Reason: ${esc(c.decline_reason)}${c.reviewed?' (reviewed)':''}</div>`:''}${c.summary?`<div>${esc(c.summary)}</div>`:''}\n <div class=\"m\">${c.telegram_sent?'Designer messaged on Telegram':''}${c.in_hubspot?' · In HubSpot':''}${c.window_missed?' · Booked outside its call-by window':''}</div></div>`).join(''):'<div class=\"m\">No calls yet.</div>';\n document.getElementById('filters').innerHTML=['all','qualified','declined','escalated','missed','info_only'].map(f=>`<button class=\"${f===filter?'on':''}\" data-f=\"${f}\">${f.replace('_',' ')}</button>`).join('');\n}\nasync function load(){\n const r=await fetch('/api/calls',{headers:{'x-api-key':key}}).then(r=>r.json());\n if(r.error){document.getElementById('list').textContent='Access key not accepted. Clear it and reload.';localStorage.removeItem('key');return}\n all=r.calls;const t=r.totals;\n document.getElementById('tiles').innerHTML=[['Calls',t.total],['Qualified',t.qualified],['Declined',t.declined],['Escalated',t.escalated],['Missed',t.missed]].map(([a,b])=>`<div class=\"tile\">${a}<b>${b}</b></div>`).join('');\n draw();\n}\ndocument.addEventListener('click',e=>{const b=e.target.closest('button[data-f]');if(b){filter=b.dataset.f;draw()}});\nload();setInterval(load,15000);\n</script></body></html>\n";
